<template>
  <AppPage class="registration-page" :title="title" :subtitle="subtitle" capability="内部登记">
    <template #action><el-button :disabled="busy" :type="trash ? 'primary' : ''" plain @click="toggleTrash">{{ trash ? '返回正常记录' : '已删除记录' }}</el-button><el-button v-if="can('import') && !trash" @click="historyVisible = true">导入记录</el-button><el-button v-if="can('import') && !trash" @click="importVisible = true">批量登记</el-button><el-button v-if="can('export')" :disabled="busy || count === null" @click="exportRecords">导出筛选结果</el-button><el-button v-if="can('create') && !trash" type="primary" :disabled="busy" @click="newRecord">新建登记</el-button></template>
    <el-alert v-if="trash" title="已删除记录：仅从正常列表移除，原登记、凭证和操作历史均保留。恢复换货登记时会重新校验当前订单及商品明细。" type="info" :closable="false" show-icon />
    <div class="metrics" aria-label="筛选结果统计"><div><span>登记总数</span><strong>{{ count ?? '—' }}</strong><small>当前筛选范围</small></div><div><span>草稿</span><strong>{{ count === null ? '—' : summary.draft || 0 }}</strong><small>尚未提交或确认</small></div><div><span>{{ kind === 'exchange' ? '待审批／待更新' : '已登记（已付款）' }}</span><strong>{{ count === null ? '—' : kind === 'exchange' ? (summary.pending || 0) + (summary.pending_update || 0) : summary.registered || 0 }}</strong><small>{{ kind === 'exchange' ? '不代表明细已更新' : '已确认实际付款' }}</small></div><div><span>{{ kind === 'exchange' ? '更新异常' : '已作废' }}</span><strong>{{ count === null ? '—' : summary[kind === 'exchange' ? 'update_failed' : 'void'] || 0 }}</strong><small>{{ kind === 'exchange' ? '需要核对并重试' : '保留原登记历史' }}</small></div></div>
    <section class="workspace-card" aria-label="登记列表">
      <form class="toolbar" aria-label="登记筛选" @submit.prevent="queryRecords">
        <el-input v-model="filters.order_number" clearable placeholder="输入完整平台订单号" aria-label="订单号筛选" />
        <el-select v-model="filters.store_id" filterable remote :remote-method="searchFilterStores" clearable placeholder="全部可见店铺" aria-label="店铺筛选"><el-option v-for="store in filterStores" :key="store.id" :label="`${store.code} · ${store.name}`" :value="store.id" /></el-select>
        <el-select v-model="filters.status" clearable placeholder="全部状态" aria-label="状态筛选"><el-option v-for="value in availableStatuses" :key="value" :label="statuses[value]" :value="value" /></el-select>
        <el-select v-if="kind === 'gcash'" v-model="filters.type" clearable placeholder="全部类型" aria-label="类型筛选"><el-option label="退款" value="refund" /><el-option label="其他" value="other" /></el-select>
        <el-date-picker v-model="dateRange" type="daterange" value-format="YYYY-MM-DD" start-placeholder="登记开始日期" end-placeholder="结束日期" range-separator="至" aria-label="登记日期范围（中国时间）" />
        <el-button type="primary" native-type="submit" :loading="busy">查询</el-button><el-button :disabled="busy" @click="resetFilters">重置</el-button><el-button :loading="busy" @click="load">刷新</el-button>
      </form>
      <div class="list-context"><span>{{ trash ? '已删除记录 · 统计按删除前状态展示' : '仅展示当前权限范围' }} · 日期按中国时间筛选</span><el-tag v-if="batchId" closable @close="clearBatch">导入批次 #{{ batchId }}</el-tag><el-button v-if="!trash && can('edit')" type="danger" plain :disabled="busy || !selectedIds.length" @click="beginBatchDelete">批量删除草稿（{{ selectedIds.length }}）</el-button><el-button v-if="!trash && kind === 'exchange' && can('submit')" :disabled="busy || !selectedIds.length || !submitSelectionAllowed" title="仅可提交本人待处理的换货登记" @click="batchSubmit">提交所选草稿审批（{{ selectedIds.length }}）</el-button></div>
      <el-alert v-if="listError" :title="listError" type="error" show-icon :closable="false" /><el-alert v-if="feedback && !editing" :title="feedback" type="success" :closable="false" />
      <el-table v-loading="busy" :data="rows" row-key="id" :empty-text="listError ? '登记读取失败，请点击刷新重试。' : trash ? '当前筛选范围暂无已删除记录。' : '暂无登记，可新建业务记录或按模板导入草稿。'" @row-click="row => open(row)" @selection-change="selection => selectedIds = selection.map(row => row.id)">
        <el-table-column v-if="!trash && (can('edit') || (kind === 'exchange' && can('submit')))" type="selection" :selectable="selectableRow" width="45" />
        <el-table-column label="登记／订单" min-width="205" fixed="left"><template #default="{ row }"><b>#{{ row.id }} · {{ row.order_number || '其他付款' }}</b><small>{{ row.store_code || '' }} · {{ row.store }}</small></template></el-table-column>
        <el-table-column v-if="kind === 'exchange'" label="商品调整" min-width="210"><template #default="{ row }"><b>{{ changeSummary(row.payload.changes) }}</b><small>{{ row.payload.reason }}</small></template></el-table-column>
        <template v-if="kind === 'promotion'"><el-table-column label="整单金额" min-width="130" align="right"><template #default="{ row }">{{ row.payload.order_amount }} {{ row.payload.currency }}</template></el-table-column><el-table-column label="推广服务费／汇率" min-width="160" align="right"><template #default="{ row }"><b>{{ row.payload.fee_amount }} {{ row.payload.fee_currency }}</b><small>汇率 {{ row.payload.exchange_rate }}</small></template></el-table-column></template>
        <el-table-column v-if="kind !== 'exchange'" :label="kind === 'gcash' ? '实际付款金额' : '登记整单成本'" min-width="145" align="right"><template #default="{ row }"><b class="numeric">{{ row.payload.cost || row.payload.amount || '—' }} {{ row.payload.currency || '' }}</b><small v-if="kind === 'gcash'">{{ row.payload.type === 'refund' ? '退款' : '其他付款' }}</small></template></el-table-column>
        <el-table-column v-if="kind === 'gcash'" label="付款日期" min-width="120"><template #default="{ row }">{{ row.payload.paid_at }}</template></el-table-column>
        <el-table-column label="状态" min-width="160"><template #default="{ row }"><el-tag :type="statusType(row.status)" size="small">{{ statuses[row.status] || row.status }}</el-tag><small v-if="kind === 'exchange'">{{ row.status === 'historical_recorded' ? '仅历史留档，不调整履约或库存' : row.detail_updated ? '内部明细已更新' : '内部明细未完成更新' }}</small></template></el-table-column>
        <el-table-column v-if="kind === 'gcash'" label="凭证" width="75"><template #default="{ row }">{{ row.evidence_count }} 张</template></el-table-column>
        <el-table-column label="登记时间／操作人" min-width="170"><template #default="{ row }">{{ formatTime(row.created_at) }}<small>{{ row.requested_by_name || '—' }}</small></template></el-table-column>
        <el-table-column v-if="trash" label="删除信息" min-width="220"><template #default="{ row }"><b>{{ formatTime(row.deleted_at) }} · {{ row.deleted_by_name }}</b><small>{{ row.delete_reason }}</small></template></el-table-column>
        <el-table-column label="操作" width="170" fixed="right"><template #default="{ row }"><el-button link type="primary" @click.stop="open(row)">详情</el-button><el-button v-if="!row.deleted_at && can('edit') && ['draft', 'rejected', 'withdrawn'].includes(row.status)" link @click.stop="open(row, true)">编辑</el-button><el-button v-if="canDelete(row)" link type="danger" :disabled="busy" @click.stop="beginLifecycle(row, 'delete')">删除</el-button><el-button v-if="row.deleted_at && can('edit')" link type="primary" :disabled="busy" @click.stop="beginLifecycle(row, 'restore')">恢复</el-button></template></el-table-column>
      </el-table>
      <el-pagination v-model:current-page="page" v-model:page-size="pageSize" :page-sizes="[20, 50, 100]" :total="count || 0" layout="total, sizes, prev, pager, next" @current-change="load" @size-change="queryRecords" />
    </section>
    <p class="boundary">{{ notice }}</p>

    <component :is="dialogMode ? ElDialog : ElDrawer" v-if="editing" class="registration-editor" :class="{ 'registration-dialog': dialogMode }" aria-label="登记详情" :model-value="editing" :title="selected ? `${title} #${selected.id}` : `新建${title}`" :width="'900px'" :size="'min(900px, 100vw)'" append-to-body :close-on-click-modal="false" :close-on-press-escape="!busy" :show-close="!busy" :before-close="beforeClose" @update:model-value="editing = $event">
      <el-alert v-if="error" :title="error" type="error" show-icon :closable="false" role="alert" /><el-alert v-if="feedback" :title="feedback" :type="selected?.status === 'update_failed' ? 'warning' : 'success'" :closable="false" /><el-alert v-if="listError && selected" :title="`登记处理结果已保留，但列表未刷新：${listError}。请勿重复提交，可关闭后刷新列表。`" type="warning" :closable="false" />
      <el-alert v-if="recovery" title="提交结果尚未确认。请先核对服务器记录，不要另建重复登记。" type="warning" :closable="false" /><div v-if="recovery" class="actions"><el-button :loading="busy" @click="recover">核对服务器结果</el-button><el-button v-if="recovery.canRetry" :loading="busy" @click="retryOriginal">重试原提交（保持原登记标识）</el-button></div>
      <el-button v-if="conflict && selected" :disabled="busy" @click="open(selected, dialogMode)">重新加载当前登记并核对</el-button>
      <div v-if="selected" class="detail-heading"><el-tag :type="statusType(selected.status)">{{ selected.deleted_at ? '已删除 · ' : '' }}{{ statuses[selected.status] }}</el-tag><span>{{ selected.store_code }} · {{ selected.store }} · {{ selected.requested_by_name || '—' }}</span><el-button v-if="!selected.deleted_at && !dialogMode && can('edit') && ['draft', 'rejected', 'withdrawn'].includes(selected.status)" type="primary" plain :disabled="busy" @click="open(selected, true)">编辑草稿</el-button><el-button v-if="!dialogMode && kind !== 'exchange' && selected.status === 'registered' && can('edit')" @click="startCorrection">更正登记（保留历史）</el-button><el-button v-if="canDelete(selected) && !dirty" type="danger" plain :disabled="busy || Boolean(recovery)" @click="beginLifecycle(selected, 'delete')">删除草稿</el-button><el-button v-if="selected.deleted_at && can('edit')" type="primary" plain :disabled="busy" @click="beginLifecycle(selected, 'restore')">恢复登记</el-button></div>
      <el-alert v-if="selected?.deleted_at" :title="`已删除：${formatTime(selected.deleted_at)} · ${selected.deleted_by_name}；原因：${selected.delete_reason}。凭证和历史保留，恢复前不可编辑或提交。`" type="info" :closable="false" />
      <el-alert v-if="selected?.status === 'historical_recorded'" title="此记录为历史补录。商品快照仅用于核对历史事实，未修改订单、待发货明细、库存或仓库数据，不能提交审批或执行换货。" type="info" :closable="false" />
      <el-alert v-if="selected?.duplicate_order_count" :title="`同一订单还有 ${selected.duplicate_order_count} 条同类登记，请核对重复业务或部分退款。`" type="warning" :closable="false" />
      <el-alert v-if="kind === 'exchange' && ['pending_update', 'update_failed'].includes(selected?.status)" title="审批已通过，但待发货明细尚未更新，登记未完成。请重试更新；若明细已变化，请取消异常申请后重新申请。" type="warning" :closable="false" />
      <template v-if="!dialogMode && selected">
        <h3>业务概览</h3><el-descriptions :column="2" border><el-descriptions-item label="订单号">{{ selected.order_number || '未关联（其他付款）' }}</el-descriptions-item><el-descriptions-item label="登记时间">{{ formatTime(selected.created_at) }}</el-descriptions-item><el-descriptions-item v-if="kind === 'promotion'" label="整单金额">{{ selected.payload.order_amount }} {{ selected.payload.currency }}</el-descriptions-item><el-descriptions-item v-if="kind === 'promotion'" label="服务费">{{ selected.payload.fee_amount }} {{ selected.payload.fee_currency }}</el-descriptions-item><el-descriptions-item v-if="kind === 'promotion'" label="汇率">1 {{ selected.payload.fee_currency }} = {{ selected.payload.exchange_rate }} {{ selected.payload.currency }}</el-descriptions-item><el-descriptions-item v-if="kind === 'promotion'" label="整单成本">{{ selected.payload.cost }} {{ selected.payload.currency }}</el-descriptions-item><el-descriptions-item v-if="kind === 'promotion'" label="汇率日期／来源" :span="2">{{ selected.payload.rate_date || '同币种不需要' }} · {{ selected.payload.rate_source || '—' }}</el-descriptions-item><el-descriptions-item v-if="kind === 'gcash'" label="实际付款">{{ selected.payload.amount }} {{ selected.payload.currency }}</el-descriptions-item><el-descriptions-item v-if="kind === 'gcash'" label="付款日期">{{ selected.payload.paid_at }}</el-descriptions-item><el-descriptions-item v-if="kind === 'gcash'" label="收款人／手机号">{{ selected.payload.recipient || '—' }} · {{ selected.payload.phone || '—' }}</el-descriptions-item><el-descriptions-item v-if="kind === 'gcash'" label="付款账户／参考号">{{ selected.payload.payment_account || '—' }} · {{ selected.payload.transaction_reference || '—' }}</el-descriptions-item><el-descriptions-item v-if="kind === 'exchange'" label="调整原因" :span="2">{{ selected.payload.reason }}</el-descriptions-item><el-descriptions-item label="备注" :span="2">{{ selected.payload.note || '—' }}</el-descriptions-item></el-descriptions>
      </template>
      <el-form v-if="dialogMode" ref="formElement" label-position="top" :disabled="busy || locked || Boolean(recovery)" @submit.prevent="save">
        <h3>关联业务</h3><div class="form-grid"><el-form-item label="店铺" required :error="fieldErrors.store_id"><el-select v-model="form.store_id" filterable remote :remote-method="searchStores" :disabled="Boolean(selected)" @change="clearOrder"><el-option v-for="store in stores" :key="store.id" :label="`${store.code} · ${store.name}`" :value="store.id" /></el-select></el-form-item><el-form-item label="平台订单号" :required="kind !== 'gcash' || form.payload.type === 'refund'" :error="fieldErrors.order_id"><div class="order-lookup"><el-input v-model="orderNumber" :disabled="Boolean(selected)" placeholder="输入完整订单号" /><el-button :disabled="!form.store_id || !orderNumber || Boolean(selected)" @click="findOrder">关联订单</el-button></div></el-form-item></div>
        <p v-if="order" class="order-note">已关联 {{ order.number }} · 来源整单金额 {{ order.source_order_amount }} {{ order.currency }} · 状态 {{ order.status }}。来源金额仅供核对，不替代人工登记金额。</p>
        <el-alert v-if="kind === 'exchange' && order?.adjustment_blockers?.length" :title="order.adjustment_blockers.join('；')" type="warning" :closable="false" />
        <template v-if="kind === 'exchange'">
          <h3>当前待发货商品</h3><el-table :data="order?.pending || []" size="small" empty-text="先关联订单，再核对当前商品和数量"><el-table-column prop="sku_code" label="SKU" min-width="130" /><el-table-column prop="product_name" label="商品" min-width="170" /><el-table-column prop="quantity" label="当前数量" width="100" /></el-table>
          <h3>商品变化</h3><p v-if="fieldErrors.changes" class="field-error">{{ fieldErrors.changes }}</p>
          <div v-for="(change, index) in form.payload.changes" :key="index" class="change-row"><div class="change-heading"><b>变化 {{ index + 1 }}</b><el-button link type="danger" @click="form.payload.changes.splice(index, 1)">删除此行</el-button></div><div class="change-grid"><el-form-item label="变化类型"><el-select v-model="change.action" @change="resetChange(change)"><el-option label="替换" value="replace" /><el-option label="增加" value="add" /><el-option label="减少" value="reduce" /></el-select></el-form-item><el-form-item v-if="change.action !== 'add'" label="原SKU"><el-select v-model="change.old_sku_id" filterable><el-option v-for="line in order?.pending || []" :key="line.sku_id" :label="`${line.sku_code || skuLabel(line.sku_id)} · 当前${line.quantity}件`" :value="line.sku_id" /></el-select></el-form-item><el-form-item v-if="change.action !== 'add'" label="减少数量"><el-input-number v-model="change.reduce_quantity" :min="1" :max="pendingQuantity(change.old_sku_id)" :precision="0" controls-position="right" /></el-form-item><el-form-item v-if="change.action !== 'reduce'" label="新SKU"><el-select v-model="change.new_sku_id" filterable remote :remote-method="searchSkus"><el-option v-for="sku in skus" :key="sku.id" :label="`${sku.sku_code} · ${sku.product_name || ''}`" :value="sku.id" /></el-select></el-form-item><el-form-item v-if="change.action !== 'reduce'" label="增加数量"><el-input-number v-model="change.add_quantity" :min="1" :precision="0" controls-position="right" /></el-form-item></div></div>
          <el-button :disabled="!order || form.payload.changes.length >= 200" @click="form.payload.changes.push({ action: 'add', add_quantity: 1 })">增加变化行</el-button><h3>调整前后预览</h3><el-table v-if="exchangePreview" :data="exchangePreview" size="small"><el-table-column label="SKU" min-width="130"><template #default="{ row }">{{ skuLabel(row.sku_id) }}</template></el-table-column><el-table-column prop="before" label="调整前数量" /><el-table-column prop="after" label="调整后数量" /></el-table><p class="muted">{{ exchangePreview ? '预览仅供核对，保存和审批时仍由服务端重新校验。' : '请补齐商品变化，数量不能超过当前待发货量，调整后至少保留一件商品。' }}</p><el-form-item label="换货原因" required :error="fieldErrors.reason"><el-input v-model="form.payload.reason" maxlength="500" /></el-form-item>
        </template>
        <template v-if="kind === 'promotion'"><h3>推广费用</h3><div class="form-grid"><el-form-item :label="`登记整单金额（${storeCurrency}）`" required :error="fieldErrors.order_amount"><el-input v-model="form.payload.order_amount" inputmode="decimal" /></el-form-item><el-form-item label="推广服务费／发包价" required :error="fieldErrors.fee_amount"><el-input v-model="form.payload.fee_amount" inputmode="decimal" /></el-form-item><el-form-item label="服务费币种" required><el-select v-model="form.payload.fee_currency"><el-option v-for="currency in currencies" :key="currency" :label="currency" :value="currency" /></el-select></el-form-item><el-form-item :label="`汇率：1 ${form.payload.fee_currency} = 若干 ${storeCurrency}`" required :error="fieldErrors.exchange_rate"><el-input v-model="form.payload.exchange_rate" :disabled="form.payload.fee_currency === storeCurrency" inputmode="decimal" /></el-form-item><el-form-item label="汇率日期" :required="crossCurrency" :error="fieldErrors.rate_date"><el-input v-model="form.payload.rate_date" type="date" /></el-form-item><el-form-item label="汇率来源" :required="crossCurrency" :error="fieldErrors.rate_source"><el-input v-model="form.payload.rate_source" placeholder="例如：人工核对的当日牌价" /></el-form-item></div><p class="order-note">成本 = 整单金额 + 服务费 × 汇率。{{ selected?.payload.cost ? `服务端已计算：${selected.payload.cost} ${selected.payload.currency}` : '保存后由服务端精确计算。' }}</p></template>
<template v-if="kind === 'gcash'"><h3>付款信息</h3><div class="form-grid"><el-form-item label="类型" required><el-select v-model="form.payload.type"><el-option label="退款（必须关联订单）" value="refund" /><el-option label="其他（必须填写用途）" value="other" /></el-select></el-form-item><el-form-item label="实际付款金额" required :error="fieldErrors.amount"><el-input v-model="form.payload.amount" inputmode="decimal" /></el-form-item><el-form-item label="凭证实际币种" required><el-select v-model="form.payload.currency"><el-option v-for="currency in currencies" :key="currency" :label="currency" :value="currency" /></el-select></el-form-item><el-form-item label="付款日期（中国时间，YYYY-MM-DD）" required :error="fieldErrors.paid_at"><el-input v-model="form.payload.paid_at" type="date" /></el-form-item><el-form-item label="收款人"><el-input v-model="form.payload.recipient" autocomplete="off" /></el-form-item><el-form-item label="收款手机号（文本，保留前导零）" :error="fieldErrors.phone"><el-input v-model="form.payload.phone" autocomplete="off" /></el-form-item><el-form-item label="付款账户标识（选填，非密码）"><el-input v-model="form.payload.payment_account" autocomplete="off" /></el-form-item><el-form-item label="交易参考号（选填）"><el-input v-model="form.payload.transaction_reference" autocomplete="off" /></el-form-item></div></template>
        <el-form-item label="备注" :required="kind === 'gcash'" :error="fieldErrors.note"><el-input v-model="form.payload.note" type="textarea" :rows="2" maxlength="500" :placeholder="kind === 'gcash' ? '请填写退款原因或其他付款用途' : '补充说明（选填）'" /></el-form-item>
        <el-form-item v-if="correcting" label="更正原因" required :error="fieldErrors.correctionReason"><el-input v-model="correctionReason" type="textarea" :rows="2" maxlength="500" /></el-form-item>
        <div class="actions"><el-button v-if="!locked && can(selected ? 'edit' : 'create')" type="primary" :loading="busy" @click="save">{{ correcting ? '保存更正（不改变实际交易）' : '保存草稿' }}</el-button><el-button v-if="correcting" @click="cancelCorrection">取消更正</el-button></div>
      </el-form>

      <template v-if="selected">
        <div v-if="kind === 'exchange'" class="snapshot-grid"><section v-for="key in ['original', 'before', 'after']" :key="key"><h3>{{ selected.snapshot?.historical ? { original: '原订单商品快照', before: '历史换货前（留档）', after: '历史换货后（仅留档，未执行）' }[key] : { original: '首次原始整单', before: '本次调整前', after: '本次最终整单' }[key] }}</h3><ul><li v-for="line in selected.snapshot?.[key]" :key="line.sku_id">{{ skuLabel(line.sku_id) }} × {{ line.quantity }}</li></ul><p v-if="!selected.snapshot?.[key]?.length">暂无明细快照</p></section></div>
