  if (kind.value === 'promotion') { amount('order_amount', storeCurrency.value); amount('fee_amount', payload.fee_currency); if (crossCurrency.value) { if (!/^\d+(\.\d{1,10})?$/.test(String(payload.exchange_rate)) || Number(payload.exchange_rate) <= 0) errors.exchange_rate = '汇率必须大于0，最多10位小数。'; if (!payload.rate_date) errors.rate_date = '跨币种请填写汇率日期。'; if (!payload.rate_source?.trim()) errors.rate_source = '跨币种请填写汇率来源。'; } }
