  if (kind.value === 'exchange') { if (!payload.reason?.trim()) errors.reason = '请填写换货原因。'; if (!payload.changes?.length) errors.changes = '至少填写一行商品变化。'; const reductions = {}; for (const row of payload.changes || []) { for (const [idKey, qtyKey, required] of [['old_sku_id', 'reduce_quantity', row.action !== 'add'], ['new_sku_id', 'add_quantity', row.action !== 'reduce']]) if (required && (!row[idKey] || !Number.isInteger(row[qtyKey]) || row[qtyKey] <= 0)) errors.changes = '请补齐每行商品和正整数数量。'; if (row.action !== 'add') reductions[row.old_sku_id] = (reductions[row.old_sku_id] || 0) + row.reduce_quantity; } for (const [id, qty] of Object.entries(reductions)) if (qty > pendingQuantity(Number(id))) errors.changes = '同一原SKU的累计减少数量不能超过当前待发货数量。'; }
  if (correcting.value && !correctionReason.value.trim()) errors.correctionReason = '更正原因不能为空。';
  fieldErrors.value = errors; return !Object.keys(errors).length;
}
async function write(config) { try { return await call(config); } catch (e) { if (!e.stale && (!e.status || e.status >= 500) && !['VALIDATION_ERROR', 'STATE_CONFLICT', 'PERMISSION_DENIED'].includes(e.code)) recovery.value = { config: JSON.parse(JSON.stringify(config)), id: selected.value?.id, key: form.idempotency_key, canRetry: false }; throw e; } }
async function save() {
  if (busy.value || recovery.value || locked.value) return;
  if (!validate()) { error.value = '请检查标记的字段，内容尚未提交。'; await nextTick(); formElement.value?.$el?.querySelector('.is-error input, .is-error textarea, .field-error')?.focus(); return; }
  await guarded(async () => { const payload = JSON.parse(JSON.stringify(form.payload)); if (kind.value === 'promotion' && payload.fee_currency === storeCurrency.value) payload.exchange_rate = '1'; if (kind.value === 'gcash' && selected.value) for (const key of ['phone', 'recipient', 'payment_account', 'transaction_reference']) if (String(payload[key] || '').startsWith('***')) delete payload[key]; const wasCorrection = correcting.value; const config = selected.value ? { method: 'patch', url: `${base()}${selected.value.id}/`, data: { payload, version: selected.value.version, reason: correcting.value ? correctionReason.value : '' } } : { method: 'post', url: base(), data: { ...form, payload } }; const data = await write(config); fillRecord(data); feedback.value = wasCorrection ? '更正已保存，历史记录保留。' : (kind.value === 'gcash' ? '草稿已保存，可继续上传凭证并核对处理。' : '草稿已保存，请核对业务内容后继续处理。'); await loadRows(); });
}
function startCorrection() { dialogMode.value = true; correcting.value = true; correctionReason.value = ''; error.value = ''; feedback.value = ''; markClean(); }
function cancelCorrection() { fillRecord(selected.value); dialogMode.value = false; markClean(); }
const actions = computed(() => {
  const row = selected.value; if (!row || row.deleted_at) return []; const result = [];
  if (kind.value === 'gcash') { if (row.status === 'draft' && can('edit')) result.push({ code: 'register', label: '确认已付款并登记' }); if (row.status === 'registered' && can('edit')) result.push({ code: 'void', label: '作废登记' }); return result; }
  if (kind.value === 'promotion') { if (['draft', 'rejected', 'withdrawn', 'approved'].includes(row.status) && can('edit')) result.push({ code: 'register', label: '确认已付款并登记' }); if (['draft', 'rejected', 'withdrawn'].includes(row.status) && can('edit')) result.push({ code: 'cancel', label: '取消登记' }); if (row.status === 'pending' && row.requested_by === auth.currentUser?.id && can('edit')) result.push({ code: 'withdraw', label: '撤回旧审批' }); if (row.status === 'registered' && can('edit')) result.push({ code: 'void', label: '作废登记' }); return result; }
  if (['draft', 'rejected', 'withdrawn'].includes(row.status)) { if (row.requested_by === auth.currentUser?.id && can('submit')) result.push({ code: 'submit', label: '提交审批' }); if (can('edit')) result.push({ code: 'cancel', label: '取消申请' }); }
  if (row.status === 'pending') { if (row.requested_by === auth.currentUser?.id && can('submit')) result.push({ code: 'withdraw', label: '撤回修改' }); else if (can('approve')) result.push({ code: 'approve', label: '审批并更新待发货明细' }, { code: 'reject', label: '驳回' }); }
  if (['pending_update', 'update_failed'].includes(row.status) && can('approve')) { result.push({ code: 'apply', label: '重试更新已批准明细' }); if (row.status === 'update_failed' && can('edit')) result.push({ code: 'cancel', label: '取消异常申请（保留审批记录）' }); }
  return result;
});
function requestAction(action) { if (dirty.value || recovery.value) return; if (['void', 'reject'].includes(action.code) && !decisionNote.value.trim()) { error.value = '请先填写作废／驳回原因。'; return; } pendingAction.value = action; error.value = ''; }
async function act(operation) { if (dirty.value || recovery.value) return; await guarded(async () => { const data = await write({ method: 'post', url: `${base()}${selected.value.id}/${operation}/`, data: { note: decisionNote.value, version: selected.value.version } }); fillRecord(data); feedback.value = data.status === 'update_failed' ? '审批已通过，但内部明细更新失败，请核对后重试更新。' : `处理完成：${statuses[data.status]}。${kind.value === 'exchange' ? '仅表示本系统处理状态。' : data.status === 'registered' ? '已确认实际付款，系统不会重复转账。' : '仅更新登记记录，不撤销实际付款。'}`; await loadRows(); }); }
async function recover() { await guarded(async () => { const pending = recovery.value; const data = await call({ url: pending.id ? `${base()}${pending.id}/` : base(), ...(pending.id ? {} : { params: { request_key: pending.key } }) }); const record = pending.id ? data : data.results?.[0]; if (record) { fillRecord(record); recovery.value = null; feedback.value = '已读取服务器最新记录，请核对状态及内容后继续。'; } else { pending.canRetry = true; error.value = '暂未查到原提交，可重试原提交；内容和登记标识保持不变，不要另建重复记录。'; } await loadRows(); }); }
async function retryOriginal() { if (!recovery.value?.canRetry) return; await guarded(async () => { const data = await write(recovery.value.config); fillRecord(data); recovery.value = null; feedback.value = '已获取原提交结果，请核对记录。'; await loadRows(); }); }
async function upload(event) { const file = event.target.files?.[0]; if (!file) return; if (file.size > 5 * 1048576 || !['image/png', 'image/jpeg'].includes(file.type)) { error.value = '请选择不超过5MB的PNG／JPEG截图。'; event.target.value = ''; return; } await guarded(async () => { const data = new FormData(); data.append('file', file); selected.value = await call({ method: 'post', url: `${base()}${selected.value.id}/evidence/`, data }); feedback.value = '凭证已保存。'; await loadRows(); }); event.target.value = ''; }
async function downloadEvidence(evidence) { await guarded(async () => { const result = await downloadApiFile(`${base()}${selected.value.id}/evidence/${evidence.id}/`, evidence.name); if (result?.success === false) throw new Error(result.message); }); }
async function previewEvidence(evidence) { await guarded(async () => { const current = generation, access = getAccessToken(), membership = sessionStorage.getItem('saas-collab.active-membership.v1'); const response = await fetch(`${apiBaseUrl}${base()}${selected.value.id}/evidence/${evidence.id}/`, { headers: { ...(access ? { Authorization: `Bearer ${access}` } : {}), ...(membership && /^\d+$/.test(membership) ? { 'X-Org-Membership': membership } : {}) } }); if (current !== generation) return; if (!response.ok) throw new Error('凭证读取失败或当前账号无查看权限。'); const blob = await response.blob(); if (current !== generation) return; if (!['image/png', 'image/jpeg'].includes(blob.type)) throw new Error('返回内容不是可预览的截图。'); clearImage(); imageUrl.value = URL.createObjectURL(blob); imageVisible.value = true; }); }
function clearImage() { if (imageUrl.value) URL.revokeObjectURL(imageUrl.value); imageUrl.value = ''; }
async function exportRecords() { await guarded(async () => { const result = await downloadApiFile(`${base()}export/?${new URLSearchParams(params())}`, `${title.value}-筛选结果.csv`); if (result?.success === false) throw new Error(result.message); feedback.value = '已开始下载当前筛选范围的登记，不包含未授权数据。'; }); }
async function batchSubmit() { await guarded(async () => { const data = await call({ method: 'post', url: `${base()}batch-submit/`, data: { ids: selectedIds.value, versions: Object.fromEntries(rows.value.filter(row => selectedIds.value.includes(row.id)).map(row => [String(row.id), row.version])) } }); await loadRows(); const errors = data.results.filter(row => !row.success); if (errors.length) listError.value = errors.map(row => `#${row.id}: ${row.error}`).join('；'); else feedback.value = '所选登记已逐单提交审批，尚未更新待发货明细。'; }); }
async function openImported(id) { importVisible.value = false; historyVisible.value = false; await open({ id }); }
async function viewBatch(id) { importVisible.value = false; historyVisible.value = false; batchId.value = id; page.value = 1; await load(); }
async function clearBatch() { batchId.value = ''; await queryRecords(); }
const refundSummary = (groups = {}) => Object.entries(groups).map(([currency, amount]) => `${amount} ${currency}`).join('；') || '暂无记录（不代表未发生退款）';
const changeSummary = (changes = []) => ['replace', 'add', 'reduce'].map(action => { const count = changes.filter(row => row.action === action).length; return count ? `${({ replace: '替换', add: '增加', reduce: '减少' })[action]}${count}项` : ''; }).filter(Boolean).join('、') || '无商品变化';
const skuLabel = id => selected.value?.sku_details?.find(s => s.id === id)?.sku_code || [...(order.value?.pending || []), ...(order.value?.original || [])].find(row => row.sku_id === id)?.sku_code || skus.value.find(s => s.id === id)?.sku_code || `SKU #${id}`;
const pendingQuantity = id => id ? order.value?.pending?.find(row => row.sku_id === id)?.quantity || 0 : 1000000;
const exchangePreview = computed(() => {
  if (!order.value || !form.payload.changes?.length) return null;
  const before = new Map(order.value.pending.map(row => [row.sku_id, row.quantity])), after = new Map(before), reductions = new Map(), additions = new Map();
