async function canDiscard() { if (busy.value || importPanel.value?.busy) return false; if (!dirty.value && !recovery.value && !importPanel.value?.hasFiles) return true; try { await ElMessageBox.confirm(recovery.value ? '提交结果尚未确认，离开前建议先核对服务器记录。仍要离开吗？' : importPanel.value?.hasFiles ? '离开会清除当前选择的文件和预览，已导入的记录不会删除。确认离开吗？' : '有尚未保存的内容，离开将丢失这些修改。确认放弃吗？', '离开登记', { confirmButtonText: '放弃并离开', cancelButtonText: '继续填写', type: 'warning' }); return true; } catch { return false; } }
async function beforeClose(done) { if (await canDiscard()) { editing.value = false; clearImage(); done(); } }
async function beforeImportClose(done) { if (importPanel.value?.busy) return; if (importPanel.value?.hasFiles) { try { await ElMessageBox.confirm('关闭会清除当前文件和预览，已确认导入的批次可在导入记录中查询。确认关闭吗？', '关闭批量登记', { confirmButtonText: '关闭', cancelButtonText: '继续核对' }); } catch { return; } } done(); }
