onBeforeRouteLeave(canDiscard); onBeforeRouteUpdate(canDiscard);
watch(orderNumber, value => { if (!selected.value && order.value && value.trim() !== order.value.number) clearOrder(); });
watch(() => form.payload.fee_currency, () => { if (kind.value === 'promotion' && form.payload.fee_currency === storeCurrency.value) form.payload.exchange_rate = '1'; });
watch(selected, row => { conflict.value = false; if (row?.deleted_at) dialogMode.value = false; });
watch(kind, () => { trash.value = false; lifecycle.visible = false; });
watch(kind, async () => { generation++; listSequence++; busy.value = false; editing.value = false; importVisible.value = false; historyVisible.value = false; imageVisible.value = false; clearImage(); selected.value = null; recovery.value = null; order.value = null; stores.value = []; skus.value = []; selectedIds.value = []; error.value = ''; feedback.value = ''; Object.assign(filters, { order_number: route.query?.order_number || '', status: '', store_id: route.query?.store_id ? Number(route.query.store_id) : '', type: '' }); dateRange.value = []; batchId.value = ''; rows.value = []; count.value = null; summary.value = {}; page.value = 1; await searchFilterStores(); await load(); });
watch(() => route.query, async () => { filters.order_number = route.query?.order_number || ''; filters.store_id = route.query?.store_id ? Number(route.query.store_id) : ''; page.value = 1; await load(); });
onMounted(async () => { filters.order_number = route.query?.order_number || ''; filters.store_id = route.query?.store_id ? Number(route.query.store_id) : ''; window.addEventListener('beforeunload', unload); await searchFilterStores(); await load(); });
onBeforeUnmount(() => { generation++; window.removeEventListener('beforeunload', unload); clearImage(); });
</script>

